 public void SetNotice(string value) { notice.Text = value; notice.Visibility = string.IsNullOrWhiteSpace(value) ? Visibility.Collapsed : Visibility.Visible; }
 public void RefreshStatus() { liveStatus.Text = app.Dictation.State == DictationState.Recording ? C("windows.status.listening","Listening") + " · " + TimeSpan.FromMilliseconds(app.Dictation.ElapsedMs).ToString(@"m\:ss") : app.Dictation.State == DictationState.Transcribing ? C("bubble.transcribing","Transcribing…") : "Ctrl + Win + Space"; if (app.Dictation.Error.Length > 0) SetNotice(app.ErrorText(app.Dictation.Error)); }
 private void BuildNav() { nav.Children.Clear(); foreach (var (id,label) in new[] { ("home",C("nav.home","Home")), ("history",C("nav.history","History")), ("settings",C("nav.settings","Settings")) }) nav.Children.Add(Action(label, () => Navigate(id), primary: route == id)); nav.Visibility = S.OnboardingComplete ? Visibility.Visible : Visibility.Collapsed; }
 private void Clear() { micTest?.Dispose(); micTest = null; page.Children.Clear(); SetNotice(""); scroll.ScrollToTop(); }
 private TextBlock Text(string value, double size = 15, bool muted = false) { var text = new TextBlock { Text = value, FontSize = size, Margin = new(0,0,0,10), LineHeight = size * 1.5 }; if (muted) text.SetResourceReference(TextBlock.ForegroundProperty,"Muted"); return text; }
 private void Heading(string title, string? subtitle = null) { page.Children.Add(new TextBlock { Text = title, FontFamily = Theme.Serif, FontSize = 28, FontWeight = FontWeights.SemiBold, Margin = new(0,0,0,10), TextWrapping = TextWrapping.Wrap }); if (subtitle != null) page.Children.Add(Text(subtitle,15,true)); }
 private StackPanel Card(string? title = null, string? subtitle = null) { var panel = new StackPanel(); if (title != null) panel.Children.Add(Text(title,17)); if (subtitle != null) panel.Children.Add(Text(subtitle,13,true)); var border = new Border { Child = panel, Padding = new(18), CornerRadius = new(16), BorderThickness = new(1), Margin = new(0,6,0,8) }; border.SetResourceReference(Border.BackgroundProperty,"Surface"); border.SetResourceReference(Border.BorderBrushProperty,"Line"); page.Children.Add(border); return panel; }
 private Button Action(string label, Action action, bool primary = false) { var b = new Button { Content = new TextBlock { Text = label, TextWrapping = TextWrapping.Wrap, TextAlignment = TextAlignment.Center, Foreground = primary ? Brushes.White : (Brush)Application.Current.Resources["BrandInk"] } }; if (primary) { b.SetResourceReference(BackgroundProperty,"Brand"); b.Foreground = Brushes.White; } b.Click += (_,_) => { try { action(); } catch (Exception e) { SetNotice(app.ErrorText(DictationController.Code(e))); } }; System.Windows.Automation.AutomationProperties.SetName(b,label); return b; }
 private Button AsyncAction(string label, Func<Task> action, bool primary = false) { Button? b = null; b = Action(label, async () => { b!.IsEnabled = false; try { await action(); } catch (OperationCanceledException) { } catch (Exception e) { SetNotice(app.ErrorText(DictationController.Code(e))); } finally { b!.IsEnabled = true; } }, primary); return b; }
 private TextBox Field(StackPanel panel, string label, string value = "", bool multiline = false) { panel.Children.Add(Text(label,12,true)); var field = new TextBox { Text = value, AcceptsReturn = multiline, TextWrapping = multiline ? TextWrapping.Wrap : TextWrapping.NoWrap, MinHeight = multiline ? 95 : 46 }; System.Windows.Automation.AutomationProperties.SetName(field,label); panel.Children.Add(field); return field; }
 private CheckBox Toggle(StackPanel panel, string label, bool value, Action<bool> changed) { var box = new CheckBox { Content = new TextBlock { Text = label, TextWrapping = TextWrapping.Wrap }, IsChecked = value }; box.Checked += (_,_) => changed(true); box.Unchecked += (_,_) => changed(false); panel.Children.Add(box); System.Windows.Automation.AutomationProperties.SetName(box,label); return box; }
 private ComboBox Choice<T>(StackPanel panel, string label, IEnumerable<T> options, T selected, Action<T> changed) { panel.Children.Add(Text(label,12,true)); var box = new ComboBox { ItemsSource = options.ToList(), SelectedItem = selected }; box.SelectionChanged += (_,_) => { if (box.SelectedItem is T value) changed(value); }; System.Windows.Automation.AutomationProperties.SetName(box,label); panel.Children.Add(box); return box; }
 private void Back() => page.Children.Add(Action(C("action.back","Back"), () => Navigate("settings")));
 private static void Open(string url) => Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
 private bool Confirm(string message) => MessageBox.Show(this,message,"Quill",MessageBoxButton.YesNo,MessageBoxImage.Warning) == MessageBoxResult.Yes;
 private void Navigate(string value) { if (!S.OnboardingComplete) return; route = value; Clear(); BuildNav(); switch (value) { case "home": Home(); break; case "history": History(); break; case "settings": SettingsIndex(); break; case "speech": Speech(); break; case "keys": Back(); Heading(C("settings.keys.title","API keys")); Keys(page, false); break; case "cleanup": Cleanup(); break; case "style": Styles(); break; case "words": Vocabulary(); break; case "contacts": Contacts(); break; case "audio": Audio(); break; case "privacy": Privacy(); break; case "bubble": Bubble(); break; case "advanced": Advanced(); break; case "about": About(); break; } RefreshStatus(); }
 private void Home() {
