  var privacy = Card(); Toggle(privacy,C("settings.privacy.private","Private mode"),S.PrivateMode,on => { S.PrivateMode = on; app.Settings.Save(); }); privacy.Children.Add(Text(C("windows.home.private_help","Private mode prevents new dictations from being saved in local history. Provider requests still go directly to the providers you choose."),13,true));
