  var test = Card(C("windows.home.try_title","Try a dictation"),C("windows.home.try_help","Click this field, then tap the bubble. Your words will appear here.")); Field(test,C("windows.home.try_field","Practice text field"),multiline:true);
  if (!app.HotkeyAvailable) page.Children.Add(Text(C("windows.home.hotkey_conflict","The keyboard shortcut is already in use by another app. The bubble and tray controls are available."),13,true));
