  foreach (var item in new[] { ("speech","windows.settings.speech","Speech & model","windows.settings.speech_sub","Provider, model and spoken language"), ("keys","settings.keys.title","API keys","windows.settings.keys_sub","Secure keys for all five providers"), ("cleanup","windows.settings.cleanup","Clean up with AI","windows.settings.cleanup_sub","Conservative cleanup, your model and key"), ("style","windows.settings.style","Writing style","windows.settings.style_sub","Neutral, formal or casual — by app"), ("words","windows.settings.words","Custom words","windows.settings.words_sub","Correct names and frequently misheard words"), ("contacts","windows.settings.contacts","Contact names","windows.settings.contacts_sub","Import names to improve recognition"), ("audio","windows.settings.audio","Audio & recording","windows.settings.audio_sub","Microphone, meter and session limit"), ("privacy","windows.settings.privacy","Privacy & history","windows.settings.privacy_sub","Private mode and local retention"), ("bubble","windows.settings.bubble","Bubble appearance","windows.settings.bubble_sub","Size, visibility and theme"), ("advanced","windows.settings.advanced","Advanced","windows.settings.advanced_sub","Startup, recovery and reset"), ("about","windows.settings.about","About Quill","windows.settings.about_sub","Privacy, licenses and diagnostics") }) { var card = Card(); card.Children.Add(Action(C(item.Item2,item.Item3) + "  →",() => Navigate(item.Item1))); card.Children.Add(Text(C(item.Item4,item.Item5),13,true)); }
