 private void Keys(StackPanel targetPanel, bool onboarding) {
  var provider = S.Provider; var box = Choice(targetPanel,C("windows.keys.provider","Provider"),Enum.GetValues<Provider>(),provider,p => { S.Provider = p; S.SpeechModel = p == Provider.Custom ? S.CustomModel : Providers.Get(p).SpeechModel; app.Settings.Save(); if (onboarding) ShowStep(2); else Navigate("keys"); });
  if (provider == Provider.Custom) { var url = Field(targetPanel,C("windows.speech.url","HTTPS base URL"),S.CustomBaseUrl); var model = Field(targetPanel,C("windows.speech.custom_model","Speech model ID"),S.CustomModel); url.LostFocus += (_,_) => S.CustomBaseUrl = url.Text.Trim(); model.LostFocus += (_,_) => S.CustomModel = model.Text.Trim(); }
  if (Providers.Get(provider).ConsoleUrl is string link) targetPanel.Children.Add(Action(C("windows.keys.get","Where do I get a key?"),() => { if (Confirm(C("windows.keys.guide","Open your provider's key console, sign in, create a key, then copy it and return here. Provider usage may incur charges."))) Open(link); }));
  foreach (var key in app.Secrets.List(provider)) { var row = new StackPanel { Margin = new(0,8,0,8) }; row.Children.Add(Text(key.Label + " · ••••" + key.LastFour + (app.Secrets.ActiveId(provider) == key.Id ? " · " + C("settings.keys.active","Active key") : ""),14)); var actions = new WrapPanel(); actions.Children.Add(Action(C("settings.keys.use","Use this key"),() => { app.Secrets.Activate(provider,key.Id); if (onboarding) ShowStep(3); else Navigate("keys"); })); actions.Children.Add(Action(C("windows.keys.delete","Delete key"),() => { if (Confirm(C("windows.keys.delete_confirm","Delete this saved key from this PC?"))) { app.Secrets.Delete(provider,key.Id); if (onboarding) ShowStep(2); else Navigate("keys"); } })); row.Children.Add(actions); targetPanel.Children.Add(row); }
  var label = Field(targetPanel,C("windows.keys.label","Key label (optional)")); targetPanel.Children.Add(Text(C("windows.keys.key","API key"),12,true)); var secret = new PasswordBox(); System.Windows.Automation.AutomationProperties.SetName(secret,C("windows.keys.key","API key")); targetPanel.Children.Add(secret);
  targetPanel.Children.Add(Text(C("windows.keys.secure","Keys are encrypted using your Windows account. They stay on this PC and are sent only to their selected provider. A rejected new key leaves your saved keys intact."),13,true));
  targetPanel.Children.Add(AsyncAction(C("windows.keys.validate","Verify & save key"),async () => { var key = secret.Password.Trim(); if (provider == Provider.Custom) { S.CustomBaseUrl = Providers.ValidateEndpoint(S.CustomBaseUrl); if (S.CustomModel.Length == 0) throw new ProviderException("model_missing"); S.SpeechModel = S.CustomModel; } SetNotice(C("windows.keys.checking","Checking your key…")); await app.Provider.ValidateKey(provider,key,S.CustomBaseUrl,CancellationToken.None); app.Secrets.Add(provider,key,label.Text); secret.Clear(); app.Settings.Save(); if (onboarding) ShowStep(3); else Navigate("keys"); },true));
  if (onboarding && app.Secrets.List(provider).Count > 0) targetPanel.Children.Add(Action(C("action.continue","Continue"),() => ShowStep(3),true));
 }
